<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php'; require_login(); $pdo=db();
if(!phase3_ready($pdo)) redirect('upgrade_phase3.php');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(post_string('action')==='read'){ $id=post_int('id');$pdo->prepare('UPDATE notifications SET is_read=1,read_at=NOW() WHERE id=? AND user_id=?')->execute([$id,current_user()['id']]);}elseif(post_string('action')==='read_all'){$pdo->prepare('UPDATE notifications SET is_read=1,read_at=NOW() WHERE user_id=? AND is_read=0')->execute([current_user()['id']]);}redirect('notifications.php');}
$st=$pdo->prepare("SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 100");$st->execute([current_user()['id']]);$items=$st->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications · SPS CRM</title><style>body{margin:0;background:#f5f7fb;font-family:Arial;color:#172033}.top{background:#fff;border-bottom:1px solid #e5eaf2;padding:18px 28px;display:flex;justify-content:space-between}.top a{color:#315ee7;text-decoration:none}.wrap{max-width:900px;margin:auto;padding:28px}.card{background:#fff;border:1px solid #e5eaf2;border-radius:15px;padding:20px}.row{padding:14px;border-bottom:1px solid #edf0f5}.unread{background:#f3f6ff}.btn{background:#315ee7;color:#fff;border:0;padding:8px 12px;border-radius:8px}.muted{color:#6d788a}</style></head><body><header class="top"><strong>SPS CRM · Notifications</strong><a href="dashboard.php">← Dashboard</a></header><main class="wrap"><div class="card"><div style="display:flex;justify-content:space-between;align-items:center"><h1>Notifications</h1><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="read_all"><button class="btn">Mark all read</button></form></div><?php foreach($items as $n):?><div class="row <?=$n['is_read']?'':'unread'?>"><strong><?=e($n['title'])?></strong><div><?=e($n['message'])?></div><div class="muted"><?=e($n['created_at'])?></div><?php if(!$n['is_read']):?><form method="post" style="margin-top:6px"><?=csrf_field()?><input type="hidden" name="action" value="read"><input type="hidden" name="id" value="<?=$n['id']?>"><button class="btn">Mark read</button></form><?php endif;?></div><?php endforeach;?><?php if(!$items):?><p>No notifications yet.</p><?php endif;?></div></main></body></html>
